inline SDL_Cursor* create(CursorType type)
{
    const uint8_t* rgba = nullptr;
    SDL_Point hotspot = getHotspot(type);

    switch (type)
    {
    case CursorType::GrabWhite:
        rgba = cursor_GrabWhite;
        break;
    case CursorType::GrabbingWhite:
        rgba = cursor_GrabbingWhite;
        break;
    default:
        return nullptr;
    }

    SDL_Surface* surf = SDL_CreateSurfaceFrom(
        Width,
        Height,
        SDL_PIXELFORMAT_RGBA32,
        (void*)rgba,
        Width * 4
    );
    if (!surf) return nullptr;

    SDL_Cursor* cursor = SDL_CreateColorCursor(surf, hotspot.x, hotspot.y);
    SDL_DestroySurface(surf);
    return cursor;
}

